-- Product page editorial content (v1, 2026-10-03).
-- Every product gets a short display name without parentheses and an
-- editorial block in products.specifications->'editorial':
--   subtitle, tagline, pack ("1 kg • Özel bez kese"), packFor (the variant
--   name the pack line describes), about (Ürün bilgileri paragraph), origin,
--   production, ingredients (+ ingredientsLabel for non-food), packaging,
--   qualifier (the old parenthetical, shown in the properties section) and
--   formerName (the previous display name, kept searchable).
-- Source of the values: catalog/product-editorial/product-editorial.v1.json,
-- written only from each product's existing story, description, ingredients
-- and pack. The admin core upsert keeps unknown specifications keys, so the
-- block survives later edits in the product editor.

-- 1. Search keeps finding products by their former names.
create or replace function private.refresh_product_search_text_v1()
returns trigger language plpgsql set search_path to '' as $function$
begin
  new.search_text:=lower(concat_ws(' ',new.name,new.short_description,new.description,new.story,new.origin,array_to_string(new.tags,' '),new.translations::text,new.specifications->'editorial'->>'formerName'));
  return new;
end;
$function$;
drop trigger if exists refresh_product_search_text_v1 on public.products;
create trigger refresh_product_search_text_v1
  before insert or update of name, short_description, description, story, origin, tags, translations, specifications
  on public.products for each row execute function private.refresh_product_search_text_v1();

-- 2. Catalogue cards carry formerName (offline search and suggestions).
do $$
declare def text := pg_get_functiondef('private.catalog_public_card_rows_live_v1()'::regprocedure);
        needle text := '''handlingProfile'',private.product_handling_profile_v1(product.id)';
begin
  if position('''formerName''' in def) = 0 then
    if position(needle in def) = 0 then raise exception 'card builder changed; formerName not added'; end if;
    execute replace(def, needle, needle || ',' || E'\n      ''formerName'',nullif(btrim(coalesce(product.specifications->''editorial''->>''formerName'','''')),'''')');
  end if;
end $$;

-- 3. The product page carries the editorial block (whitelisted keys only).
create or replace function private.get_public_product_detail_v12(p_reference text)
returns jsonb language plpgsql stable security definer set search_path to '' as $function$
declare
  base jsonb := private.get_public_product_detail_v11(p_reference);
  source jsonb;
  editorial jsonb := '{}'::jsonb;
  key text;
begin
  if base = '{}'::jsonb or base is null then return base; end if;
  select p.specifications->'editorial' into source
  from public.products p where p.id = private.resolve_product_id_v1(p_reference);
  if jsonb_typeof(source) = 'object' then
    foreach key in array array['subtitle','tagline','pack','packFor','about','origin','production','ingredients','ingredientsLabel','packaging','qualifier','formerName'] loop
      if jsonb_typeof(source->key) = 'string' and btrim(source->>key) <> '' then
        editorial := editorial || jsonb_build_object(key, left(btrim(source->>key), 1200));
      end if;
    end loop;
  end if;
  return base || jsonb_build_object('editorial', case when editorial = '{}'::jsonb then null else editorial end);
end;
$function$;
revoke all on function private.get_public_product_detail_v12(text) from public, anon, authenticated;

create or replace function api_public_bridge.get_public_product_detail_v6(p_reference text)
returns jsonb language sql stable security definer set search_path to ''
as $function$ select private.get_public_product_detail_v12(p_reference); $function$;

-- 4. Content: short names and the editorial block, matched by id and slug.
update public.products p
   set name = r->>'name',
       specifications = jsonb_set(coalesce(p.specifications,'{}'::jsonb), '{editorial}', r->'editorial', true)
  from jsonb_array_elements($editorial$[{"id":"aae99128-f40e-4bc7-929e-f896c00ab313","slug":"abidin-in-yayla-kuzusu-302","name":"Yayla Kuzusu","editorial":{"subtitle":"Yayla otuyla büyür, siparişinize göre kesilir","tagline":"Hazırda bekletilmez; adınıza ayrılır, helal usulle kesilir.","pack":"Bütün kuzu • Ort. 16–20 kg","packFor":"1 Bütün Kuzu (Ort. 16-20 kg)","about":"Yayla Kuzusu, yaz boyunca Yeşiltaş'ın üstündeki yaylalarda analarının yanında, açık havada büyüyen kuzulardan seçilir. Sipariş verdiğinizde adınıza ayrılır, helal usulle kesilir ve istediğiniz gibi parçalanır.","origin":"Yüksekova / Oremar","production":"Yayla otlatması, siparişle helal kesim","ingredients":"Kuzu eti","formerName":"Abidin'in Yayla Kuzusu"}},{"id":"bfd5e5f6-a2c0-4511-815a-d83f0be8ef78","slug":"amine-nin-cifte-sari-koy-yumurtasi-305","name":"Çifte Sarı Köy Yumurtası","editorial":{"subtitle":"İri yumurtalar arasından tek tek seçilir","tagline":"Tavaya kırdığınızda iki sarıyı yan yana görürsünüz.","pack":"30 adet • Özel viyol koli","packFor":"30 Adet (Özel Viop Koli)","about":"Çifte Sarı Köy Yumurtası, gün boyu bahçede ve merada gezen köy tavuklarının iri yumurtaları arasından her sabah tek tek seçilir. Kabuğu çatlak, ince ya da kirli olanlar ayrılır; otuz yumurta viyole dizilip özenle paketlenir.","origin":"Yüksekova / Oremar","production":"Serbest gezen köy tavukları, elle seçim","ingredients":"Köy tavuğu yumurtası","packaging":"Viyol koli","formerName":"Amine'nin Çifte Sarı Köy Yumurtası"}},{"id":"ae324353-9844-4b34-a71e-491942b4182d","slug":"ata-tohumu-dag-kekigi-suyu-distile-807","name":"Dağ Kekiği Suyu","editorial":{"subtitle":"Dağ kekiğinin imbikten geçirilmiş aromatik suyu","tagline":"Kekik kaynar, buharı soğur, damla damla şişeye iner.","pack":"500 ml • Cam şişe","packFor":"500 ml Cam Şişe","about":"Dağ Kekiği Suyu, yaz başında yamaçlardan toplanan kekiğin imbikte suyla kaynatılması ve buharının soğutularak damla damla toplanmasıyla elde edilen aromatik bir sudur. Suyla seyreltilerek, birkaç damla kullanılır; tıbbi bir ürün olarak sunulmaz.","origin":"Yüksekova / Oremar","production":"İmbikte damıtma","qualifier":"Distile, imbikten geçirilmiş","ingredients":"Dağ kekiği, su","packaging":"Cam şişe","formerName":"Ata Tohumu Dağ Kekiği Suyu (Distile)"}},{"id":"dc2c2378-ad63-4bbe-9eab-882165939e54","slug":"avasin-cam-damacana-suyu-401","name":"Dağ Kaynak Suyu","editorial":{"subtitle":"Avaşin kaynağından, cam damacanada","tagline":"Su dağdan gelir, cama girer, başka hiçbir şeye değmez.","pack":"19 L • Cam damacana","packFor":"19 Litre Cam","about":"Dağ Kaynak Suyu, Avaşin'in yamaçlarından süzülen ve köyde kuşaklardır içme suyu olarak kullanılan kaynak suyudur. Damacanalar kaynağın başında, sipariş üzerine doldurulur; cam, suya koku ya da tat geçirmez.","origin":"Yüksekova / Oremar","production":"Kaynağında, sipariş üzerine dolum","ingredients":"Kaynak suyu","packaging":"Cam damacana","formerName":"Avaşin Cam Damacana Suyu"}},{"id":"dc5c8644-550a-4033-82e1-5637301c277a","slug":"avasin-deresi-canli-alabaligi-ozel-hasat-301","name":"Dere Alabalığı","editorial":{"subtitle":"Avaşin deresinin soğuk akar suyundan","tagline":"Sipariş geldiğinde dereden tutulur, aynı gün buzla yola çıkar.","pack":"1,5–2 kg • Taze, bütün","packFor":"Min. 1.5 - 2 kg Taze Bütün","about":"Dere Alabalığı, Avaşin deresinin yazın bile soğuk akan suyunda büyür; akıntıya karşı yüzdüğü için eti sıkı, dokusu diridir. Balık önceden tutulup bekletilmez; sipariş geldiğinde tutulur, aynı gün temizlenir ve buzla paketlenir.","origin":"Yüksekova / Oremar","production":"Siparişle hasat, soğuk zincir","qualifier":"Özel hasat","ingredients":"Taze alabalık","packaging":"Buzlu paket","formerName":"Avaşin Deresi Canlı Alabalığı (Özel Hasat)"}},{"id":"c17f9a67-5560-449c-a8f2-a372f1625f88","slug":"avasin-mese-bali-103","name":"Meşe Balı","editorial":{"subtitle":"Avaşin vadisinin meşeliğinden, koyu ve ağır kıvamlı","tagline":"Meşe yapraklarındaki tatlı salgıdan, arının geç mevsim emeğiyle.","pack":"1 kg • Cam kavanoz","packFor":"1 kg Cam Kavanoz","about":"Meşe Balı, Avaşin vadisindeki meşelerin yapraklarında yaz sonuna doğru biriken salgının arılar tarafından toplanmasıyla oluşan bir salgı balıdır. Rengi koyu kehribardan kahverengiye çalar, kıvamı ağırdır; tadında çiçek balından daha tok, hafif buruk bir derinlik vardır.","origin":"Yüksekova / Oremar","production":"Salgı balı, geç mevsim hasadı","ingredients":"Süzme meşe (salgı) balı","packaging":"Cam kavanoz","formerName":"Avaşin Meşe Balı"}},{"id":"aaabee02-be61-45ca-9007-bba163cf77c0","slug":"bercelan-yaylasi-bahar-cicek-bali-102","name":"Bahar Çiçek Balı","editorial":{"subtitle":"Berçelan yaylasının bahar çiçeklerinden","tagline":"Karın çekildiği haftalarda açan yayla çiçeklerinden, sabırla süzüldü.","pack":"1 kg • Cam kavanoz","packFor":"1 kg Cam Kavanoz","about":"Bahar Çiçek Balı, Berçelan yaylasında bahar çiçeklerinin açtığı haftalarda yaylaya çıkarılan kovanlardan elde edilir. Petekler hasatta süzülür, bal bir süre dinlendirildikten sonra cam kavanoza doldurulur. Açık renklidir; zamanla kristalleşmesi doğaldır.","origin":"Yüksekova / Oremar","production":"Yayla arıcılığı, süzme bal","ingredients":"Süzme çiçek balı","packaging":"Cam kavanoz","formerName":"Berçelan Yaylası Bahar Çiçek Balı"}},{"id":"89e97a7f-66f5-45e4-9a1f-7af1185f9dd9","slug":"buyuk-iskender-corek-otu-tohumu-705","name":"Çörek Otu","editorial":{"subtitle":"Köy tarlasından, elle elenmiş iri taneler","tagline":"Harmanda savrulur, elekten geçer, taşı tek tek ayıklanır.","pack":"500 g • Bez kese","packFor":"500 gr Kese","about":"Çörek Otu, köy tarlasında yetişen bitkinin yaz sonunda olgunlaşan kapsüllerinden elde edilir. Harmanda dövülüp rüzgârda savrulan tohum elekten geçirilir; taş, sap ve boş taneler elle ayıklanır.","origin":"Yüksekova / Oremar","production":"Harman ve elle eleme","ingredients":"%100 çörek otu tohumu","packaging":"Bez kese","formerName":"Büyük İskender Çörek Otu Tohumu"}},{"id":"6e2b45bf-b3cc-4cc4-bc56-b7d87ef89552","slug":"dag-cilegi-yabani-803","name":"Yabani Dağ Çileği","editorial":{"subtitle":"Yamaçta kendiliğinden yetişir, sabah serinliğinde toplanır","tagline":"Kimse ekmedi; bir avuç dağ çileği bütün odayı kokutur.","pack":"1 kg • Kutu","packFor":"1 kg Kutu","about":"Yabani Dağ Çileği, Yeşiltaş'ın üstündeki yamaçlarda kar suyunun geçtiği nemli, yarı gölge yerlerde kendiliğinden biter. Mevsimi kısadır; çilekler sabahın serinliğinde tek tek, ezilmeden toplanır.","origin":"Yüksekova / Oremar","production":"Doğadan elle toplama","ingredients":"Yabani dağ çileği","packaging":"Kutu","formerName":"Dağ Çileği (Yabani)"}},{"id":"1347f7c2-9a3b-4622-ad85-53e70238ffaf","slug":"daglica-karakovan-petek-bali-101","name":"Karakovan Petek Balı","editorial":{"subtitle":"Dağlıca yamaçlarından, yılda bir kez hasat edilir","tagline":"Arının kendi ördüğü petekte; süzülmeden, ısıtılmadan sofranıza gelir.","pack":"1 kg • Ahşap kutu","packFor":"1 kg Ahşap Kutu","about":"Karakovan Petek Balı, Dağlıca'nın kayalık yamaçlarına yerleştirilen karakovanlarda arının kendi ördüğü peteklerden kesilir. Petek süzülmez, sıkılmaz ve ısıtılmaz; mumuyla birlikte, olduğu gibi ahşap kutuya yerleştirilir. Peteğin rengi ve kokusu, o yıl yaylada hangi çiçeğin bol açtığına göre değişir.","origin":"Yüksekova / Oremar","production":"Karakovan arıcılığı, yılda tek hasat","ingredients":"Petekli bal (bal ve balmumu)","packaging":"Ahşap kutu","formerName":"Dağlıca Karakovan Petek Balı"}},{"id":"56a24565-7268-49db-9715-2ba08035d265","slug":"eksi-karadut-suyu-804","name":"Ekşi Karadut Suyu","editorial":{"subtitle":"Odun ateşinde koyulaştırılır, şeker eklenmez","tagline":"Ekşiliği de hafif tatlılığı da tamamen duttan gelir.","pack":"1 L • Cam şişe","packFor":"1 Litre Cam Şişe","about":"Ekşi Karadut Suyu, yaz ortasında toplanan olgun karadutların ezilip süzülmesi ve elde edilen suyun odun ateşinde ağır ağır kaynatılarak koyulaştırılmasıyla hazırlanır. İçine şeker girmez; suyla seyreltilerek içilir.","origin":"Yüksekova / Oremar","production":"Odun ateşinde koyulaştırma","ingredients":"%100 karadut","packaging":"Cam şişe","formerName":"Ekşi Karadut Suyu"}},{"id":"24a412fc-19d6-4e82-8e9f-78dae33acce8","slug":"el-isciligi-mese-palamudu-ekmegi-505","name":"Meşe Palamudu Ekmeği","editorial":{"subtitle":"Ekşi mayalı, beş günde hazırlanan esmer köy somunu","tagline":"Palamut toplanır, kavrulur, un olur; somun odun fırınında ağır ateşte pişer.","pack":"1,5 kg • Dev somun","packFor":"1 Adet Dev Somun (1.5 kg)","about":"Meşe Palamudu Ekmeği, sonbaharda toplanan palamutların acısı alınıp kurutulması, kavrulması ve una dönüştürülmesiyle başlar. Hamur ekşi mayayla tutulur ve günlerce dinlenir; somun odunla ısıtılan fırında pişer. Sipariş üzerine hazırlanır.","origin":"Yüksekova / Oremar","production":"Ekşi maya, odun fırını","formerName":"El İşçiliği Meşe Palamudu Ekmeği"}},{"id":"feb5bc4c-e9f6-4d79-bbc9-e1afe4b9af2d","slug":"el-islemesi-tahta-kasik-ve-yayik-tokmagi-704","name":"Tahta Kaşık ve Yayık Tokmağı","editorial":{"subtitle":"Ardıç ve şimşirden, elle oyulmuş","tagline":"Ağaç önce bekletilir, sonra lifi takip edilerek elle oyulur.","pack":"Kaşık + tokmak seti","packFor":"1 Adet Kaşık + Tokmak Seti","about":"Tahta Kaşık ve Yayık Tokmağı, gölgede kurumaya bırakılan ardıç ve şimşir parçalarından bıçak ve törpüyle elle oyulur. Yüzey, elde ve ağızda pürüz kalmayana kadar zımparalanır; üretici beyanına göre vernik ve boya sürülmez.","origin":"Yüksekova / Oremar","production":"El oyması","ingredients":"Ardıç ve şimşir ağacı","ingredientsLabel":"Malzeme","formerName":"El İşlemesi Tahta Kaşık ve Yayık Tokmağı"}},{"id":"b40c1609-2274-4dc8-9716-377a0f027dfa","slug":"fahrettin-in-sutten-kesilmis-oglagi-303","name":"Sütten Kesilmiş Oğlak","editorial":{"subtitle":"Yamaç keçilerinden, siparişinize göre kesilir","tagline":"Açık renkli, yumuşak dokulu; bayram ve misafir sofralarının yemeği.","pack":"Bütün oğlak • 10–14 kg","packFor":"1 Adet Bütün Oğlak (10-14 kg)","about":"Sütten Kesilmiş Oğlak, yamaçlarda taşlık ve çalılık arazide otlayan keçilerin, sütten kesildikleri dönemdeki oğlaklarından seçilir. Siparişiniz geldiğinde kesilir, isteğinize göre parçalanır ve soğuk zincirle gönderilir.","origin":"Yüksekova / Oremar","production":"Siparişle kesim, soğuk zincir","ingredients":"Oğlak eti","formerName":"Fahrettin'in Sütten Kesilmiş Oğlağı"}},{"id":"d810734a-c147-4fa5-a7b6-7182ff5c8ed1","slug":"gunes-sirri-guzu-yagi-ic-yag-701","name":"Kuzu İç Yağı","editorial":{"subtitle":"Kısık ateşte eritilip süzülmüş","tagline":"Eski köy mutfaklarında yemeğin asıl tadı bu yağdan gelirdi.","pack":"1 kg • Kavanoz","packFor":"1 kg Bez Kavanoz","about":"Kuzu İç Yağı, kesimden sonra ayrılan iç yağın zarlarından temizlenip küçük parçalara bölünmesi ve büyük bir kazanda kısık ateşte eritilip temiz bir bezden süzülmesiyle hazırlanır. Sıcakken berraktır; soğuyunca beyazlaşıp katılaşır.","origin":"Yüksekova / Oremar","production":"Kısık ateşte eritme, süzme","ingredients":"%100 eritilmiş kuzu iç yağı","packaging":"Kavanoz","formerName":"Güneş Sırrı Guzu Yağı (İç Yağ)"}},{"id":"35d9cc53-6667-44d5-90c3-3e4132a46d81","slug":"gunluk-taze-civik-sut-sagimdan-kapiya-204","name":"Günlük Taze Süt","editorial":{"subtitle":"Şafakta elle sağılır; kaynatılmamış çiğ inek sütü","tagline":"Sabah sağılır, aynı gün cam şişede yola çıkar.","pack":"3 L • Cam şişe","packFor":"3 Litre (Cam Şişe)","about":"Günlük Taze Süt, köy meralarında otlayan ineklerden şafak vakti elle sağılır, temiz bir bezden süzülür ve hiçbir işlemden geçirilmeden cam şişelere doldurulur. Çiğ süttür; içilmeden önce mutlaka kaynatılmalıdır.","origin":"Yüksekova / Oremar","production":"Elle sağım, ısıl işlemsiz","qualifier":"Sağımdan kapıya","ingredients":"%100 çiğ inek sütü","packaging":"Cam şişe","formerName":"Günlük Taze Cıvık Süt (Sağımdan Kapıya)"}},{"id":"d16f52a6-f3af-40f8-b309-6f310d5d2c06","slug":"hakkari-dag-elmasi-801","name":"Dağ Elması","editorial":{"subtitle":"İki bin metrenin üzerinde, yerel cins ağaçlarda yetişir","tagline":"Gündüz güneş, gece ayaz; eti sert, suyu ve kokusu bol.","pack":"1 kg • File","packFor":"1 kg File","about":"Dağ Elması, Hakkâri'nin dağlarında iki bin metrenin üzerindeki bahçelerde, yerel cins ağaçlarda yavaş olgunlaşır. Ağaçlara ilaç atılmaz; elmalar bu yüzden market elması gibi kusursuz ve aynı boyda değildir.","origin":"Yüksekova / Oremar","production":"Yüksek rakımda, ilaç atılmadan","ingredients":"Taze elma","packaging":"File","formerName":"Hakkari Dağ Elması"}},{"id":"8a0cf6ca-12b9-405f-b3f1-015720bab8fb","slug":"hakkari-dag-erigi-902","name":"Dağ Eriği","editorial":{"subtitle":"Ekşisiyle tatlısı dengede, ince kabuklu","tagline":"Ağaç sallanmaz; erikler dalından tek tek elle toplanır.","pack":"1 kg • Kasa","packFor":"1 kg Kasa","about":"Dağ Eriği, yaz sonunda yamaçtaki ağaçların en güneşli dallarında olgunlaşan küçük taneli, sulu bir yayla eriğidir. Erikler dalından elle toplanır; kabuğundaki beyazımsı doğal pus tabakası yıkanınca kolayca gider.","origin":"Yüksekova / Oremar","production":"Mevsiminde elle toplama","ingredients":"Taze dağ eriği","packaging":"Kasa","formerName":"Hakkâri Dağ Eriği"}},{"id":"a82bd3bf-b288-4c62-919b-a762e9c059e9","slug":"hakkari-ham-propolisi-907","name":"Ham Propolis","editorial":{"subtitle":"Kovan çerçevelerinden elle kazınır, işlenmeden paketlenir","tagline":"Yüz gramlık bir paketin ardında birçok kovanın emeği var.","pack":"100 g • Paket","packFor":"100 g Paket","about":"Ham Propolis, arıların ağaç tomurcukları ve kabuklarından topladığı reçineli maddelerle kovanlarını sağlamlaştırmak için ürettiği yapışkan bir arı ürünüdür. Bal hasadından sonra çerçeveler tek tek kazınır; parçalar yabancı maddelerden elle ayıklanır, eritilmez ve alkolde çözülmez.","origin":"Yüksekova / Oremar","production":"Elle kazıma, işlenmemiş","ingredients":"Ham propolis","packaging":"Paket","formerName":"Hakkâri Ham Propolisi"}},{"id":"f09dcaeb-f8ac-4200-8a3e-a4344505f188","slug":"hakkari-yayla-karpuzu-905","name":"Yayla Karpuzu","editorial":{"subtitle":"Serin gecelerde geç olgunlaşır; içi sıkı ve kıtır","tagline":"Olgun karpuz tok ve derin bir ses verir; her biri ona göre seçilir.","pack":"Ort. 5 kg • Bütün karpuz","packFor":"1 Adet (ort. 5 kg)","about":"Yayla Karpuzu, Yüksekova'nın sıcak gündüzleri ve serin gecelerinde ovadakinden geç olgunlaşır. Tarla her gün dolaşılır; sapın yanındaki filize, toprağa değen yüzün rengine ve vurulduğunda çıkan sese bakılarak olgun olanlar tek tek seçilir.","origin":"Yüksekova / Oremar","production":"Yayla yetiştiriciliği, tek tek seçim","ingredients":"Taze karpuz","formerName":"Hakkâri Yayla Karpuzu"}},{"id":"79ea7368-1e8a-49c9-ac02-939a584d661f","slug":"hardaliye-geleneksel-805","name":"Hardaliye","editorial":{"subtitle":"Üzüm şırası ve hardal tohumuyla hazırlanan geleneksel içecek","tagline":"Ne şıra ne şarap; bağ bozumunun bereketini koruyan eski bir içecek.","pack":"1 L • Cam şişe","packFor":"1 Litre Cam Şişe","about":"Hardaliye, bağ bozumunda ezilen olgun üzümlerin şırasına ezilmiş hardal tohumu katılıp serin ve karanlık bir yerde haftalarca dinlendirilmesiyle hazırlanır. Hardal tohumu alkollü fermantasyonu baskılar; ortaya hafif buruk ve mayhoş bir içecek çıkar.","origin":"Yüksekova / Oremar","production":"Geleneksel fermantasyon","qualifier":"Geleneksel","ingredients":"Üzüm şırası, hardal tohumu","packaging":"Cam şişe","formerName":"Hardaliye (Geleneksel)"}},{"id":"611e8fdc-6775-4312-9c6e-3c3769ebc731","slug":"hatun-ana-nin-eksi-maya-gunesi-tarhana-501","name":"Ekşi Mayalı Tarhana","editorial":{"subtitle":"Yaz sebzeleri ve köy yoğurduyla, güneşte kurutulmuş","tagline":"Yazın yoğrulur, damda kurur, kışın sıcak bir çorba olur.","pack":"1 kg • Keten torba","packFor":"1 kg Keten Torba","about":"Ekşi Mayalı Tarhana, mevsim sebzelerinin köy yoğurdu ve unla yoğrulup ekşi mayasıyla günlerce ekşitilmesiyle hazırlanır. Hamur küçük parçalara ayrılır, damda güneşte kurutulur, elle ufalanır ve elekten geçirilir.","origin":"Yüksekova / Oremar","production":"Ekşi mayayla fermantasyon, güneşte kurutma","ingredients":"Buğday unu, köy yoğurdu, mevsim sebzeleri, ekşi maya","packaging":"Keten torba","formerName":"Hatun Ana'nın Ekşi Maya Güneşi (Tarhana)"}},{"id":"1e22e0e3-3bd3-4359-8b1d-e83eb7501a54","slug":"havahan-in-otlu-dag-peyniri-203","name":"Otlu Dağ Peyniri","editorial":{"subtitle":"Sirmo, heliz ve mendo otlarıyla, salamurada dinlenir","tagline":"Baharın körpe dağ otları telemeye yoğrulur, kaya tuzunda olgunlaşır.","pack":"1 kg • Kalıp","packFor":"1 kg Kalıp","about":"Otlu Dağ Peyniri, baharda Avaşin meralarından elle toplanan sirmo, heliz ve mendo otlarının taze telemeye bolca yoğrulmasıyla hazırlanır. Kalıplar kaya tuzuyla hazırlanan salamuraya yatırılır ve aylarca dinlenir.","origin":"Yüksekova / Oremar","production":"Elle toplanan otlar, salamurada olgunlaştırma","ingredients":"Süt, dağ otları (sirmo, heliz, mendo), kaya tuzu, peynir mayası","packaging":"Kalıp","formerName":"Havahan'ın Otlu Dağ Peyniri"}},{"id":"d55e016b-ec47-4f92-a900-a2550e6917c5","slug":"husnu-dayi-nin-kagit-kabuklu-cevizi-504","name":"Kağıt Kabuklu Ceviz","editorial":{"subtitle":"Gölgede kurutulmuş, ince kabuklu köy cevizi","tagline":"Kabuğu avuçta kırılır; içi açık renkli ve tatlı kalır.","pack":"1 kg • File","packFor":"1 kg File","about":"Kağıt Kabuklu Ceviz, yaşlı ceviz ağaçlarından sonbaharda kendiliğinden düşen cevizlerin toplanıp yeşil kabuk artıklarından temizlenmesi ve gölgede, hava alan bir yerde yavaşça kurutulmasıyla hazırlanır. Kabuğu incedir, kolayca kırılır.","origin":"Yüksekova / Oremar","production":"Gölgede doğal kurutma","ingredients":"%100 ceviz","packaging":"File","formerName":"Hüsnü Dayı'nın Kağıt Kabuklu Cevizi"}},{"id":"1b401442-df5f-4b88-a578-100e7bcf9242","slug":"isli-kaya-uzumleri-tane-kuru-506","name":"İsli Kaya Üzümü","editorial":{"subtitle":"Doğal kurutulmuş, geleneksel yöntemlerle hazırlanmış","tagline":"Dağ havasında yetişen üzümlerden, geleneksel yöntemlerle kurutuldu.","pack":"1 kg • Özel bez kese","packFor":"1 kg Özel Bez Kese","about":"İsli Kaya Üzümü, bağ bozumundan sonra seçilen dolgun salkımların odun ateşinin isinde, günler içinde yavaş yavaş kurutulmasıyla hazırlanır. Taneler elle ayıklanır; geleneksel üretim anlayışını koruyan bu ürün, katkısız yapısıyla doğrudan sofranıza ulaşır.","origin":"Yüksekova / Oremar","production":"Odun isinde geleneksel kurutma","qualifier":"Tane kuru","ingredients":"%100 kuru üzüm","packaging":"Özel bez kese","formerName":"İsli Kaya Üzümleri (Tane Kuru)"}},{"id":"9fa01408-b682-4600-a19b-dc7126519c1e","slug":"kadin-imecesi-odun-atesi-pekmezi-503","name":"Odun Ateşi Pekmezi","editorial":{"subtitle":"Bakır kazanda, imece usulü koyulaştırılmış üzüm pekmezi","tagline":"Şeker eklenmeden; yalnızca üzüm şırası, odun ateşi ve sabır.","pack":"1 kg • Cam kavanoz","packFor":"1 kg Cam Kavanoz","about":"Odun Ateşi Pekmezi, bağ bozumunda köyün kadınlarının birlikte ezdiği üzümlerin şırasının bakır kazanda, odun ateşinde saatlerce kaynatılmasıyla hazırlanır. İçine şeker girmez; kıvamına kaşıktan akışına bakılarak, tecrübeyle karar verilir.","origin":"Yüksekova / Oremar","production":"Bakır kazanda, odun ateşinde kaynatma","ingredients":"%100 üzüm şırası","packaging":"Cam kavanoz","formerName":"Kadın İmecesi Odun Ateşi Pekmezi"}},{"id":"1780065a-28ac-4261-a2ef-13c39d299195","slug":"kan-kirmizi-yabani-kizilcik-surubu-seti-602","name":"Yabani Kızılcık Şurubu","editorial":{"subtitle":"Koyu kırmızı ve mayhoş; suyla açılarak içilir","tagline":"Sert dallar arasından tek tek toplanır, kıvam alana kadar pişirilir.","pack":"1 L konsantre • İskenderun şişe","packFor":"1 Litre Konsantre (İskenderun Şişe)","about":"Yabani Kızılcık Şurubu, dağ yamaçlarındaki yabani kızılcık ağaççıklarından yaz sonunda toplanan meyvelerin ayıklanıp kaynatılması, süzülerek çekirdeklerinden ayrılması ve kıvam alana kadar pişirilmesiyle hazırlanır. Bir ölçü şurup üç-dört ölçü suyla açılır.","origin":"Yüksekova / Oremar","production":"Kaynatma ve süzme","packaging":"Cam şişe","formerName":"Kan Kırmızı Yabani Kızılcık Şurubu Seti"}},{"id":"61bdf13e-fb75-4033-b584-3dc43de678d1","slug":"kekik-aromali-kesik-yogurt-kurud-703","name":"Kekikli Kurut","editorial":{"subtitle":"Süzme yoğurttan, güneşte kurutulmuş kışlık","tagline":"Her topakta yapanın parmak izi kalır; kışın sulandırılıp sofraya gelir.","pack":"1 kg • Bez çuval","packFor":"1 kg Bez Çuval (Parça Peynir)","about":"Kekikli Kurut, bez torbalarda süzülen yoğurdun tuzlanıp dağ kekiğiyle tatlandırılması, avuçta topak hâline getirilmesi ve günlerce güneşte kurutulmasıyla hazırlanır. Kullanmadan önce kırılıp ılık suda bekletilerek sulandırılır.","origin":"Yüksekova / Oremar","production":"Süzme ve güneşte kurutma","qualifier":"Kurutulmuş kesik yoğurt","ingredients":"Süzme yoğurt, tuz, dağ kekiği","packaging":"Bez çuval","formerName":"Kekik Aromalı Kesik Yoğurt (Kurud)"}},{"id":"77e8ba53-ccb1-41ef-9151-98a44be1469a","slug":"kekik-aromali-visne-kompostosu-809","name":"Kekikli Vişne Kompostosu","editorial":{"subtitle":"Dağ kekiğiyle, odun ateşinde kaynatılır","tagline":"Bir tutam dağ kekiği, vişnenin ekşisini yumuşatır.","pack":"1 L • Cam şişe","packFor":"1 Litre Cam Şişe","about":"Kekikli Vişne Kompostosu, yaz ortasında dalından toplanan olgun vişnelerin çekirdekleriyle birlikte odun ateşinde kaynatılması ve kaynama sırasında bir tutam dağ kekiği eklenmesiyle hazırlanır. Sıcakken cam şişelere doldurulur.","origin":"Yüksekova / Oremar","production":"Odun ateşinde kaynatma","packaging":"Cam şişe","formerName":"Kekik Aromalı Vişne Kompostosu"}},{"id":"060ab141-6901-4364-9bac-8d47382ab9aa","slug":"kirik-tas-kaya-tuzu-blogu-kristal-603","name":"Kristal Kaya Tuzu","editorial":{"subtitle":"Kayadan kırıldığı gibi, öğütülmeden","tagline":"Yıkanmaz, rafine edilmez; dağdan kırıldığı hâliyle çuvala girer.","pack":"5 kg • Çuval, iri parçalar","packFor":"Büyük Parçalar (5 kg Çuval)","about":"Kristal Kaya Tuzu, tuz ocağından iri parçalar hâlinde kırılan kaya tuzudur. Parçalar yıkanmaz, rafine edilmez ve öğütülmez; her biri kayanın farklı bir katmanından geldiği için görünüşleri birbirinden farklıdır.","origin":"Yüksekova / Oremar","production":"Ocaktan kırma, işlenmemiş","ingredients":"%100 kaya tuzu","packaging":"Çuval","formerName":"Kırık Taş Kaya Tuzu Bloğu (Kristal)"}},{"id":"84714717-f619-4a84-9181-603252bd00c3","slug":"kislik-kurutulmus-cennet-hurmasi-808","name":"Kuru Cennet Hurması","editorial":{"subtitle":"İpe dizilip asılarak kurutulmuş bütün meyve","tagline":"Saçak altında haftalarca kurur; dışı kuru, içi yumuşak kalır.","pack":"500 g • Kutu","packFor":"500 gr Kutu","about":"Kuru Cennet Hurması, sonbaharda sert ve dolgunken toplanan hurmaların elle soyulup ipe dizilmesi ve saçak altında, rüzgâr alan ama yağmur görmeyen bir yerde asılarak kurutulmasıyla hazırlanır.","origin":"Yüksekova / Oremar","production":"Geleneksel askıda kurutma","ingredients":"%100 kurutulmuş cennet hurması","packaging":"Kutu","formerName":"Kışlık Kurutulmuş Cennet Hurması"}},{"id":"ec7df8a1-4b85-4b5c-b440-aeae1b17f781","slug":"kitir-taze-cagla-badem-806","name":"Taze Çağla","editorial":{"subtitle":"Çekirdeği oluşmadan toplanan ekşi ve kıtır çağla","tagline":"Mevsimi iki üç haftadır; kaçırılırsa bir sonraki baharı beklemek gerekir.","pack":"1 kg • Sepet","packFor":"1 kg Sepet","about":"Taze Çağla, baharda badem ağaçlarının çiçekleri döküldükten sonra beliren ve içindeki çekirdek henüz sertleşmemişken toplanan genç bademdir. Sabah serinliğinde dalından tek tek toplanır; bütün olarak, tuza banılarak yenir.","origin":"Yüksekova / Oremar","production":"Günlük elle toplama","qualifier":"Olgunlaşmamış badem","ingredients":"Taze çağla (olgunlaşmamış badem)","packaging":"Sepet","formerName":"Kıtır Taze Çağla (Badem)"}},{"id":"e02d17fb-8b41-4361-9971-365135631d61","slug":"koylu-isi-aci-kirmizi-biber-706","name":"Acı Pul Biber","editorial":{"subtitle":"Damda güneşte kurutulmuş, iri dövülmüş","tagline":"Biber damda kızarır, havanda dövülür; pulu görünür kalır.","pack":"500 g • Cam şişe","packFor":"500 g cam şişe","about":"Acı Pul Biber, yaz sonunda tam kırmızıya dönen acı biberlerin ipe dizilip damda güneşte kurutulması ve havanda iri iri dövülmesiyle hazırlanır. Tohumlarıyla birlikte dövüldüğü için acısı belirgindir.","origin":"Yüksekova / Oremar","production":"Güneşte kurutma, havanda dövme","ingredients":"%100 acı kırmızı biber","packaging":"Cam şişe","formerName":"Köylü İşi Acı Kırmızı Biber"}},{"id":"b510b051-a5d7-47cd-9795-878573dd27f8","slug":"koyun-efsanevi-beyaz-isitma-pres-tasi-402","name":"Beyaz Isıtma ve Pres Taşı","editorial":{"subtitle":"Oval, elle tıraşlanmış doğal taş","tagline":"Köy evlerinde kışın ısı tutmak, mutfakta bastırmak için kullanılan taş.","pack":"2–4 kg • Oval tıraşlı taş","packFor":"1 Adet Oval Tıraşlı Taş (2-4 kg)","about":"Beyaz Isıtma ve Pres Taşı, çatlaksız ve sık dokulu beyaz taşlar arasından seçilip oval biçimde tıraşlanan geleneksel bir ev eşyasıdır. Isı tutma ve pres taşı olarak kullanılır; tıbbi amaçla sunulmaz.","origin":"Yüksekova / Oremar","production":"Elle seçme ve tıraşlama","ingredients":"Doğal beyaz taş","ingredientsLabel":"Malzeme","formerName":"Köyün Efsanevi Beyaz Isıtma/Pres Taşı"}},{"id":"c5e47259-5b24-4b03-a3ed-da1f16899448","slug":"kusburnu-marmelati-707","name":"Kuşburnu Marmelatı","editorial":{"subtitle":"Yabani kuşburnundan, ince bezden süzülerek","tagline":"Dikenli çalıdan toplanır, saatlerce süzülür, kadife bir kıvama ulaşır.","pack":"1 kg • Cam kavanoz","packFor":"1 kg Büyük Cam","about":"Kuşburnu Marmelatı, sonbaharda dağ yamaçlarındaki yaban gülü çalılarından toplanan kuşburnularının haşlanıp ince bezden ve elekten defalarca süzülmesi ve pişirilmesiyle hazırlanır. Meyvenin tüylü çekirdekleri marmelata geçmez.","origin":"Yüksekova / Oremar","production":"Süzme ve pişirme","packaging":"Cam kavanoz","formerName":"Kuşburnu Marmelatı"}},{"id":"963b8bfa-8e7a-432d-b809-7cc4306c62e7","slug":"merez-hatun-un-magara-tulum-peyniri-201","name":"Mağara Tulum Peyniri","editorial":{"subtitle":"Kaya mağarasında sekiz ay olgunlaşır","tagline":"Şirden mayasıyla tutulur, tuluma basılır, mağaranın serinliğinde dinlenir.","pack":"1 kg • Kese","packFor":"1 kg Kese","about":"Mağara Tulum Peyniri, şirden mayasıyla mayalanan sütten elde edilen telemenin süzülüp tuzlanması, elle ufalanarak tuluma basılması ve yaz kış aynı serinlikteki kaya mağarasında sekiz ay olgunlaştırılmasıyla hazırlanır.","origin":"Yüksekova / Oremar","production":"Şirden mayası, mağarada 8 ay olgunlaştırma","ingredients":"Süt, şirden mayası, tuz","packaging":"Kese","formerName":"Merez Hatun'un Mağara Tulum Peyniri"}},{"id":"7517d0c2-e0fe-4c6b-99fe-b6e38925a1df","slug":"naciye-nin-yayik-tereyagi-202","name":"Yayık Tereyağı","editorial":{"subtitle":"İnek sütü kaymağından, ahşap yayıkta dövülür","tagline":"Yayığın sesi değişince yağ gelir; elle yıkanır, rulo yapılır.","pack":"1 kg • Rulo","packFor":"1 kg Rulo","about":"Yayık Tereyağı, günlerce biriktirilip kıvamını bulan inek sütü kaymağının ahşap yayıkta kol gücüyle dövülmesiyle elde edilir. Toplanan yağ soğuk suyla birkaç kez yıkanır, elle yoğrulur ve rulo hâline getirilir.","origin":"Yüksekova / Oremar","production":"Ahşap yayıkta elle dövme","ingredients":"%100 inek sütü kaymağı","packaging":"Rulo","formerName":"Naciye'nin Yayık Tereyağı"}},{"id":"d80d915b-5653-43c9-868e-d376a50095fd","slug":"sabir-kurutmasi-cicek-bamyasi-702","name":"Kuru Çiçek Bamyası","editorial":{"subtitle":"İpe dizilip gölgede kurutulur, yeşil rengini korur","tagline":"Her sabah tek tek toplanır, akşamları iğneyle ipe dizilir.","pack":"1 dizi • 50–60 cm","packFor":"1 Dizin (50 - 60 cm Parça)","about":"Kuru Çiçek Bamyası, sarı çiçeği döküldükten hemen sonra beliren minik bamyaların sabah erkenden toplanması, iğneyle ipe dizilmesi ve güneş görmeyen, hava alan bir çardakta kurutulmasıyla hazırlanır. Gölgede yavaş kuruduğu için yeşil rengini korur.","origin":"Yüksekova / Oremar","production":"Gölgede, ipte kurutma","ingredients":"%100 çiçek bamyası","packaging":"İpe dizili","formerName":"Sabır Kurutması Çiçek Bamyası"}},{"id":"dffffd4a-d660-40df-a682-76cf868858c7","slug":"salih-in-meralik-ozgur-horozu-304","name":"Meralık Köy Horozu","editorial":{"subtitle":"Merada serbest gezer; eti sıkı ve koyu","tagline":"Kısık ateşte saatlerce kaynar, suyu altın sarısı olur.","pack":"2,5–3 kg • Bütün horoz","packFor":"1 Adet (2.5 - 3 kg)","about":"Meralık Köy Horozu, gün boyu merada gezen, toprağı eşeleyip akşam kendiliğinden kümese dönen horozlardan seçilir. Yavaş büyüdüğü ve bol hareket ettiği için eti koyu ve sıkıdır; helal usulle kesilir.","origin":"Yüksekova / Oremar","production":"Serbest gezen, helal kesim","ingredients":"Horoz eti","formerName":"Salih'in Meralık Özgür Horozu"}},{"id":"e9941a2c-b441-496c-ae09-6564cba5d3a4","slug":"sami-usta-nin-kurutulmus-dag-dutlari-502","name":"Kuru Dağ Dutu","editorial":{"subtitle":"Güneşte kurutulmuş iri beyaz dut","tagline":"Dalından bezin üstüne dökülür, damda güneşle kurur.","pack":"1 kg • Hava almaz paket","packFor":"1 kg Hava Almaz Paket","about":"Kuru Dağ Dutu, yazın ağaçta tam olgunlaşan iri beyaz dutların sap ve yapraklarından ayıklanıp damda, temiz bezler üzerinde güneşte kurutulmasıyla hazırlanır. Kuruma süresince ara ara çevrilir; dokusu gevrek, tadı yoğun ve tatlıdır.","origin":"Yüksekova / Oremar","production":"Güneşte geleneksel kurutma","ingredients":"%100 kuru beyaz dut","packaging":"Hava almaz paket","formerName":"Sami Usta'nın Kurutulmuş Dağ Dutları"}},{"id":"787138cf-3248-48e1-a48f-da6ef43aacba","slug":"sessiz-orman-kuzu-gobegi-mantari-601","name":"Kuzu Göbeği Mantarı","editorial":{"subtitle":"Baharda ormandan toplanır; mevsimlik ve sınırlı","tagline":"Kökünden sökülmez, bıçakla kesilir; orman gelecek yıl yine versin diye.","pack":"500 g • Vakum paket","packFor":"500g Vakum Servis","about":"Kuzu Göbeği Mantarı, baharda yağmurlardan sonra ormanda yalnızca birkaç hafta görünen, bal peteğini andıran şapkasıyla tanınan yabani bir mantardır. Kökünden sökülmeden bıçakla kesilir; çiğ tüketilmez, iyice pişirilmelidir.","origin":"Yüksekova / Oremar","production":"Doğadan toplama, mevsimlik","ingredients":"Kuzu göbeği mantarı (Morchella)","packaging":"Vakum paket","formerName":"Sessiz Orman Kuzu Göbeği Mantarı"}},{"id":"65325abe-33ec-4588-9bcb-b3a9c3e85cb5","slug":"sobalik-mese-yarigi-403","name":"Sobalık Meşe Odunu","editorial":{"subtitle":"Kuru meşeden yarılmış, soba ve şömine boyunda","tagline":"Geç tutuşur, uzun yanar; közü kuzinede yemeğe yeter.","pack":"30 kg • Tel kafes bağlamı","packFor":"30 kg Tel Kafes Bağlamı","about":"Sobalık Meşe Odunu, kurumuş ağaçtan kesilip soba ve şömineye girecek boyda yarılan, açık havada istiflenerek kurutulan meşe odunudur. Tel kafes içinde, otuz kiloluk bağ hâlinde gönderilir.","origin":"Yüksekova / Oremar","production":"Yarma ve açık havada kurutma","ingredients":"Kuru meşe odunu","ingredientsLabel":"Malzeme","packaging":"Tel kafes","formerName":"Sobalık Meşe Yarığı"}},{"id":"30c7f86c-8b8b-4518-b0ad-bd9574227536","slug":"tas-degirmen-yuksekova-bulguru-908","name":"Taş Değirmen Bulguru","editorial":{"subtitle":"Yerli buğdaydan, taş değirmende kırılmış","tagline":"Kazanda kaynar, damda kurur, taş değirmende yavaşça kırılır.","pack":"1 kg • Paket","packFor":"1 kg Paket","about":"Taş Değirmen Bulguru, yerli buğdayın büyük kazanlarda kaynatılıp damda güneşte kurutulması ve taş değirmende, taneyi fazla ısıtmadan yavaş yavaş kırılmasıyla hazırlanır. Böylece bulgurun kokusu ve tadı yerinde kalır.","origin":"Yüksekova / Oremar","production":"Güneşte kurutma, taş değirmen","ingredients":"%100 buğday bulguru","packaging":"Paket","formerName":"Taş Değirmen Yüksekova Bulguru"}},{"id":"b3744415-7a3b-406a-8874-641ce3512beb","slug":"taze-yayik-ayrani-canli-kultur-205","name":"Yayık Ayranı","editorial":{"subtitle":"Köy yoğurdundan, ahşap yayıkta çekilir","tagline":"Tereyağı alındıktan sonra yayıkta kalan, köyün asıl ayranı.","pack":"2 L • Cam şişe","packFor":"2 Litre (Cam Sişe)","about":"Yayık Ayranı, köy yoğurdunun suyla birlikte ahşap yayıkta dövülüp tereyağının ayrılmasından sonra geriye kalan içecektir. Üzerinde küçük tereyağı zerreleri yüzer; ekşiliği yoğurdun kendi mayasından gelir.","origin":"Yüksekova / Oremar","production":"Ahşap yayıkta çalkalama","qualifier":"Yoğurt kaynaklı canlı maya içerebilir","ingredients":"Köy yoğurdu, su","packaging":"Cam şişe","formerName":"Taze Yayık Ayranı (Canlı Kültür)"}},{"id":"70fc64fc-3a22-4a63-a3b7-59dfd257687e","slug":"yuksekova-sonbahar-armudu-901","name":"Sonbahar Armudu","editorial":{"subtitle":"Yerel cins ağaçlardan, dalından elle toplanır","tagline":"Gündüz güneşi şekerini toplar, gece ayazı kokusunu içinde tutar.","pack":"1 kg • Kasa","packFor":"1 kg Kasa","about":"Sonbahar Armudu, Yüksekova'da serinleyen eylül gecelerinde olgunlaşan, yörenin yerel cinsi armut ağaçlarından toplanır. Armutlar silkelenmeden, dalından tek tek koparılır ve kasaya birbirine bastırılmadan dizilir.","origin":"Yüksekova / Oremar","production":"Elle toplama, küçük parti","ingredients":"Taze armut","packaging":"Kasa","formerName":"Yüksekova Sonbahar Armudu"}},{"id":"1e90c6db-fa50-4b05-84f1-2f2224f04f21","slug":"yuksekova-yayla-domatesi-802","name":"Yayla Domatesi","editorial":{"subtitle":"Ata tohumundan, yaylada toprakta yetişir","tagline":"Dalından koparıldığı an kokusu bütün bahçeye yayılır.","pack":"1 kg • Seçme","packFor":"1 kg Seçme","about":"Yayla Domatesi, her yıl bahçenin kendi domatesinden ayrılan ata tohumundan yetişir. Suni gübre verilmez, domates doğrudan toprakta büyür; serin yayla gecelerinde yavaş kızarır.","origin":"Yüksekova / Oremar","production":"Ata tohumu, toprakta yetiştirme","ingredients":"Taze domates","formerName":"Yüksekova Yayla Domatesi"}},{"id":"ab665608-64ee-4430-8924-b4167a7f4889","slug":"yuksekova-yayla-kayisisi-903","name":"Yayla Kayısısı","editorial":{"subtitle":"Kısa yayla yazında olgunlaşan küçük taneli kayısı","tagline":"Küçük tanesine yoğun bir koku sığar; bir kasa bütün mutfağı kokutur.","pack":"1 kg • Tek kat kasa","packFor":"1 kg Kasa","about":"Yayla Kayısısı, yüksek rakımın kısa yazında gündüz güneşi ve gece serinliğiyle olgunlaşır. Kayısılar dalında olgunlaşmaya bırakılır, elle toplanır ve tek kat kasaya yan yana dizilir.","origin":"Yüksekova / Oremar","production":"Dalında olgunlaşma, elle toplama","ingredients":"Taze kayısı","packaging":"Tek kat kasa","formerName":"Yüksekova Yayla Kayısısı"}},{"id":"9aba0066-f8ad-4519-9008-61208a745897","slug":"yuksekova-yayla-poleni-906","name":"Yayla Poleni","editorial":{"subtitle":"Yayla çiçeklerinden, gölgede kurutulmuş renkli taneler","tagline":"Kovana yetecek kadarı her zaman arıya bırakılarak toplanır.","pack":"250 g • Paket","packFor":"250 g Paket","about":"Yayla Poleni, arıların yayla çiçeklerinden toplayıp kovana taşıdığı renkli tanelerden oluşur. Kovan girişine yerleştirilen polen tuzağıyla toplanan taneler gölgede, havadar bir yerde kurutulur ve ayıklanır.","origin":"Yüksekova / Oremar","production":"Polen tuzağı, gölgede kurutma","ingredients":"Arı poleni","packaging":"Paket","formerName":"Yüksekova Yayla Poleni"}},{"id":"fafb2050-d147-43a7-a278-f0edf3abcb0c","slug":"yuksekova-yaz-hiyari-904","name":"Yaz Hıyarı","editorial":{"subtitle":"Sabah serinliğinde toplanan ince kabuklu, çıtır hıyar","tagline":"Güneş toprağı ısıtmadan toplanır; çıtırlığını en iyi o saatte korur.","pack":"1 kg • Kasa","packFor":"1 kg Kasa","about":"Yaz Hıyarı, Yüksekova'nın yaz bahçelerinde sabah erkenden, yapraklar henüz çiğle ıslakken toplanır. Hıyarlar boylarına göre ayrılır: küçükler turşuya, ortalar salataya gider.","origin":"Yüksekova / Oremar","production":"Sabah hasadı","ingredients":"Taze hıyar","packaging":"Kasa","formerName":"Yüksekova Yaz Hıyarı"}},{"id":"adfee0a8-15f5-4253-9881-870e89536a2a","slug":"zahter-harmani-dag-kekigi-507","name":"Dağ Kekiği","editorial":{"subtitle":"Yüksek yamaçlardan, gölgede kurutulmuş","tagline":"Çiçeğe durduğu günlerde makasla kesilir, yeşil rengini koruyarak kurur.","pack":"250 g • Büyük boy kutu","packFor":"250 gr (Büyük Boy Kutu)","about":"Dağ Kekiği, yüksek yamaçlarda taşların arasında kendiliğinden biten kekiğin yaz başında, çiçeğe durduğu dönemde makasla toplanıp serin, gölge ve hava alan bir yerde asılarak kurutulmasıyla hazırlanır. Kuruyan demetler ovularak yapraklar saplarından ayrılır.","origin":"Yüksekova / Oremar","production":"Doğadan toplama, gölgede kurutma","ingredients":"%100 kurutulmuş dağ kekiği","packaging":"Kutu","formerName":"Zahter Harmanı Dağ Kekiği"}}]$editorial$::jsonb) r
 where p.id = (r->>'id')::uuid and p.slug = r->>'slug' and p.deleted_at is null;
